        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
        int count = 0;
        int maxRight = 0;
        for (int[] cur : intervals) {
            if (cur[1] > maxRight) {
                count++;
                maxRight = cur[1];
            }
        }
        return count;
    }
}

